		{"shared-b", "alpha"},
		{"upper", "ALPHA"},
		{"other", "beta"},
	}
	for _, seed := range seeds {
		response := doJSON(t, handler, http.MethodPost, "/v1/idempotency/records", submitBody(seed.key, seed.fingerprint, `{}`, ""))
