	now := time.Now().UTC()

	expiredID, err := store.NewRecordID()
	if err != nil {
		t.Fatalf("new id: %v", err)
	}
	expired := store.Record{
		ID:                 expiredID,
		IdempotencyKey:     "gone",
		RequestFingerprint: "alpha",
		ResponseSnapshot:   []byte(`"secret"`),
		CreatedAt:          now.Add(-2 * time.Hour),
