+		{"garbage cursor", "/v1/idempotency/history?key=k&cursor=!!!not-base64", "invalid_cursor"},
+		{"json missing fields", "/v1/idempotency/history?key=k&cursor=" + url.QueryEscape(base64EncodeJSON(`{}`)), "invalid_cursor"},
